// 버전 추출 함수
function extractVersion(projectName) {
  // v4, v2, v6 등의 버전 추출
  const versionMatch = projectName.match(/v(\d+)/i);
  if (versionMatch) {
    return `v${versionMatch[1]}`;
  }

  // phase 패턴
  const phaseMatch = projectName.match(/phase\d+/i);
  if (phaseMatch) {
    return phaseMatch[0].toLowerCase();
  }

  // 숫자.숫자 패턴 (RAG 시리즈)
  const seriesMatch = projectName.match(/(\d+\.\d+)/);
  if (seriesMatch) {
    return `series-${seriesMatch[1]}`;
  }

  return 'latest';
}

// 모든 프로젝트에 version 필드 추가
projects.forEach(p => {
  if (!p.version) {
    p.version = extractVersion(p.name);
  }
});

// 저장
fs.writeFileSync('projects.json', JSON.stringify(projects, null, 2));

console.log('✅ 버전 정보 추가 완료!\n');

// 버전별 통계
