projects.forEach(p => {
  versions[p.version] = (versions[p.version] || 0) + 1;
});

console.log('버전별 분포:');
Object.entries(versions)
  .sort((a, b) => {
    // v4 > v6 > v2 > latest > phase > series 순서
    const order = { v4: 0, v6: 1, v2: 2, latest: 3, phase: 4, series: 5 };
    const aOrder = a[0].includes('v') ? (a[0] === 'v4' ? 0 : a[0] === 'v6' ? 1 : a[0] === 'v2' ? 2 : 3) : 
                   a[0].includes('phase') ? 4 : a[0].includes('series') ? 5 : 3;
    const bOrder = b[0].includes('v') ? (b[0] === 'v4' ? 0 : b[0] === 'v6' ? 1 : b[0] === 'v2' ? 2 : 3) : 
                   b[0].includes('phase') ? 4 : b[0].includes('series') ? 5 : 3;
    return aOrder - bOrder;
  })
